import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Liste","description":"Einträge kompakt untereinander darstellen und manuell sortieren.","frontmatter":{"title":"Liste","description":"Einträge kompakt untereinander darstellen und manuell sortieren."},"headers":[],"relativePath":"ansichten/liste.md","filePath":"ansichten/liste.md","lastUpdated":1786086174000}'),a={name:"ansichten/liste.md"};function s(l,e,o,d,h,u){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="liste" tabindex="-1">Liste <a class="header-anchor" href="#liste" aria-label="Permalink to &quot;Liste&quot;">​</a></h1><p>Die <strong>Liste</strong> stellt Einträge kompakt untereinander dar — platzsparender als die Tabelle und auf schmalen Bildschirmen besser lesbar.</p><p><strong>Geeignet für:</strong> Aufgabenlisten, Checklisten, Prioritätenlisten, mobile Nutzung, eingebettete Übersichten in <a href="/docs/seiten/portal-veroeffentlichen">Portalen</a>.</p><h2 id="liste-anlegen" tabindex="-1">Liste anlegen <a class="header-anchor" href="#liste-anlegen" aria-label="Permalink to &quot;Liste anlegen&quot;">​</a></h2><ol><li>Wählen Sie unter dem Grid <strong>Ansicht erstellen</strong>.</li><li>Wählen Sie <strong>Liste</strong>.</li></ol><p>Die Liste braucht <strong>keine besondere Spalte</strong> und funktioniert sofort.</p><h2 id="manuelle-reihenfolge-per-drag-drop" tabindex="-1">Manuelle Reihenfolge per Drag &amp; Drop <a class="header-anchor" href="#manuelle-reihenfolge-per-drag-drop" aria-label="Permalink to &quot;Manuelle Reihenfolge per Drag &amp; Drop&quot;">​</a></h2><p>Der wichtigste Unterschied zur Tabelle: Einträge lassen sich <strong>von Hand</strong> in eine Reihenfolge bringen, indem Sie sie ziehen.</p><div class="warning custom-block"><p class="custom-block-title">Sortierung schaltet Drag &amp; Drop ab</p><blockquote><p><em>Drag-and-drop ist deaktiviert solange Sortierung aktiv ist.</em></p></blockquote><p>Sobald eine Sortierung aktiv ist, bestimmt diese die Reihenfolge — die manuelle Anordnung wäre sonst wirkungslos.</p><p><strong>Wollen Sie von Hand sortieren, entfernen Sie zuerst die Sortierung der Ansicht.</strong></p></div><div class="tip custom-block"><p class="custom-block-title">Manuelle Reihenfolge oder Sortierung — eine Entscheidung</p><p>Beides zusammen geht nicht. Überlegen Sie, was für Ihren Fall trägt:</p><ul><li><strong>Manuelle Reihenfolge</strong> für Prioritäten, Abläufe und alles, wo die Reihenfolge eine bewusste Entscheidung ist.</li><li><strong>Sortierung</strong> für alles, was sich aus den Daten ergibt — Fälligkeit, Betrag, Name.</li></ul><p>Brauchen Sie beides, legen Sie zwei Ansichten an: eine sortierte zum Auswerten und eine manuelle zum Priorisieren.</p></div><h2 id="welche-felder-erscheinen" tabindex="-1">Welche Felder erscheinen <a class="header-anchor" href="#welche-felder-erscheinen" aria-label="Permalink to &quot;Welche Felder erscheinen&quot;">​</a></h2><p>Wie in jeder Ansicht über die sichtbaren Spalten. Da die Liste kompakt ist, lohnt sich das Ausblenden besonders.</p><p>→ <a href="/docs/ansichten/spalten-verwalten">Spalten verwalten</a></p><h2 id="filter-und-gruppierung" tabindex="-1">Filter und Gruppierung <a class="header-anchor" href="#filter-und-gruppierung" aria-label="Permalink to &quot;Filter und Gruppierung&quot;">​</a></h2><p>Wirken wie in jeder Ansicht.</p><div class="tip custom-block"><p class="custom-block-title">Gruppierte Liste als Übersicht</p><p>Eine Liste, gruppiert nach einem Statusfeld, ergibt eine kompakte Alternative zum <a href="/docs/ansichten/kanban">Kanban-Board</a> — besonders auf schmalen Bildschirmen, wo nebeneinanderliegende Spalten unpraktisch sind.</p></div><p>→ <a href="/docs/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><h2 id="liste-in-einer-seite-einbetten" tabindex="-1">Liste in einer Seite einbetten <a class="header-anchor" href="#liste-in-einer-seite-einbetten" aria-label="Permalink to &quot;Liste in einer Seite einbetten&quot;">​</a></h2><p>Die Liste eignet sich gut für <a href="/docs/seiten/was-sind-seiten">Seiten und Portale</a>: Über den Block <strong>Grid Ansicht</strong> binden Sie sie ein, und über die Blockeinstellungen steuern Sie, ob Besucher suchen, filtern und Einträge öffnen dürfen.</p><p>Für frei gestaltete Listen gibt es zusätzlich den Block <strong>Grid Liste</strong>, bei dem Sie das Aussehen jedes Listeneintrags selbst bauen.</p><p>→ <a href="/docs/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/ansichten/was-ist-eine-ansicht">Was ist eine Ansicht</a></li><li><a href="/docs/ansichten/kanban">Kanban</a></li><li><a href="/docs/ansichten/spalten-verwalten">Spalten verwalten</a></li></ul>',23)])])}const g=n(a,[["render",s]]);export{p as __pageData,g as default};
